package org.brightstats.model;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import org.brightstats.model.TypedDiagram.*;
import org.brightstats.model.ElementType.Family;
import org.brightstats.stats.*;
public final class DiagramProcessChecks {
    static int checks;static void check(boolean value){checks++;if(!value)throw new AssertionError("PROCESS diagram check "+checks);}
    static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid PROCESS diagram accepted");}catch(IllegalArgumentException expected){checks++;}}
    static Node variable(String id,ElementType type,String label,String... columns){JsonObject properties=new JsonObject();JsonArray values=new JsonArray();for(String name:columns)values.add(name);properties.add("columns",values);return new Node(id,type,label,100,100,properties);}
    static Link link(String id,ElementType type,String source,String target){return new Link(id,type,source,target,new JsonObject());}
    public static void main(String[] args)throws Exception{
        List<String> names=List.of("X1","X2","M1","M2","Y1","Y2","C");Random random=new Random(525);double[][] data=new double[300][7];for(var row:data){double x=random.nextGaussian(),c=random.nextGaussian(),m=.6*x+.3*c+.3*random.nextGaussian(),y=.5*m+.2*x+.4*c+.3*random.nextGaussian();row[0]=x+.05*random.nextGaussian();row[1]=x+.05*random.nextGaussian();row[2]=m+.05*random.nextGaussian();row[3]=m+.05*random.nextGaussian();row[4]=y+.05*random.nextGaussian();row[5]=y+.05*random.nextGaussian();row[6]=c;}
        var rootProperties=new JsonObject();rootProperties.addProperty("focalSource","x");rootProperties.addProperty("focalTarget","y");var root=new Node("root",ElementType.ROOT,"PROCESS",0,0,rootProperties);var document=new Document(1,Family.PROCESS,"root",List.of(root,variable("x",ElementType.PROCESS_MODEL_LATENT_VARIABLE,"X","X1","X2"),variable("m",ElementType.PROCESS_MODEL_LATENT_VARIABLE,"M","M1","M2"),variable("y",ElementType.PROCESS_MODEL_LATENT_VARIABLE,"Y","Y1","Y2"),variable("c",ElementType.PROCESS_MODEL_CONTROL_VARIABLE,"Covariate","C")),List.of(link("xm",ElementType.CONNECTION_BETWEEN_PROCESS_LV_AND_PROCESS_LV,"x","m"),link("my",ElementType.CONNECTION_BETWEEN_PROCESS_LV_AND_PROCESS_LV,"m","y"),link("xy",ElementType.CONNECTION_BETWEEN_PROCESS_LV_AND_PROCESS_LV,"x","y")),List.of());var compiled=DiagramProcess.compile(document,names,data);check(compiled.names().size()==11);check(compiled.model().source()==7&&compiled.model().target()==9);check(Arrays.equals(compiled.model().controls(),new int[]{10}));double[][] derived=compiled.observations();for(int row=0;row<data.length;row++){check(Math.abs(derived[row][7]-(data[row][0]+data[row][1])/2)<1e-15);check(derived[row][10]==data[row][6]);for(int col=0;col<7;col++)check(derived[row][col]==data[row][col]);}check(data[0].length==7);var fit=PathProcess.fit(derived,compiled.names(),compiled.model(),PathProcess.Options.defaults(),List.of());var total=fit.effects().stream().filter(effect->effect.family().equals("Total")).findFirst().orElseThrow();check(Math.abs(total.value()-.5)<.12);
        var props=document.node("x").properties();props.addProperty("aggregation","SUM");var sum=DiagramProcess.compile(document.with(new Node("x",ElementType.PROCESS_MODEL_LATENT_VARIABLE,"X",0,0,props)),names,data);check(Math.abs(sum.observations()[0][7]-2*derived[0][7])<1e-15);JsonObject anchorProperties=new JsonObject();anchorProperties.addProperty("edge","xy");var quadratic=document.with(new Node("anchor",ElementType.DONGLE,"",0,0,anchorProperties)).with(new Node("quadratic",ElementType.PROCESS_MODEL_QUADRATIC_EFFECT,"X squared",0,0,new JsonObject())).with(link("square",ElementType.CONNECTION_BETWEEN_PROCESS_QUADRATIC_EFFECT_AND_INDEPENT_TO_DEPENDENT_LV_CONNECTION,"quadratic","anchor"));var nonlinear=DiagramProcess.compile(quadratic,names,data);check(nonlinear.extensions().size()==1&&Arrays.equals(nonlinear.extensions().getFirst().factors(),new int[]{0,0}));check(nonlinear.extensions().getFirst().target()==2);check(quadratic.remove(Set.of("xy")).nodes().stream().noneMatch(node->node.id().equals("quadratic")||node.id().equals("anchor")));
        var wrongRoot=new Node("root",ElementType.ROOT,"PROCESS",0,0,new JsonObject());reject(()->DiagramProcess.compile(document.with(wrongRoot),names,data));var unsupported=document.node("x").properties();unsupported.addProperty("aggregation","STANDARDIZED_MEAN");reject(()->DiagramProcess.compile(document.with(new Node("x",ElementType.PROCESS_MODEL_LATENT_VARIABLE,"X",0,0,unsupported)),names,data));
        Path output=Path.of(args[0]);Files.createDirectories(output);var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();JsonObject evidence=new JsonObject();evidence.add("diagram",document.json());evidence.add("observations",gson.toJsonTree(data));evidence.add("compiled",gson.toJsonTree(compiled));evidence.add("fit",gson.toJsonTree(fit));Files.writeString(output.resolve("process-compiled.json"),gson.toJson(evidence));System.out.println("{\"checks\":"+checks+",\"derived_columns\":4}");
    }
}
